const express = require("express");
const PDFDocument = require("pdfkit");
const { pool } = require("../db/init");
const { requireAuth } = require("../middleware/auth");

const router = express.Router();

const LOGO_B64 = "";
const LOGO_BUFFER = Buffer.from(LOGO_B64, "base64");

const INK = "#12233F";
const BRASS = "#A6772C";
const BRASS_LIGHT = "#C9A464";
const SLATE = "#55606E";

const ROLE_LABELS = {
  student: "STUDENT",
  faculty: "FACULTY",
  mentor: "MENTOR",
  staff: "STAFF",
  boardDirector: "BOARD OF DIRECTORS",
  boardAdvisor: "BOARD OF ADVISORS",
};

function drawCard(doc, { roleLabel, name, idNumber, lines }) {
  const W = 340, H = 220, x = (doc.page.width - W) / 2, y = 80;

  doc.save();
  doc.rect(x, y, W, H).fill(INK);
  doc.rect(x, y, W, 44).fill(INK);
  doc.fillColor("#fff").fontSize(13).font("Helvetica-Bold").text("NATION BUILDERS UNIVERSITY", x + 60, y + 16, { width: W - 70 });
  doc.image(LOGO_BUFFER, x + 12, y + 6, { width: 32, height: 32 });
  doc.rect(x, y + 44, W, 4).fill(BRASS);

  doc.fontSize(9).fillColor(BRASS_LIGHT).font("Helvetica-Bold").text("WASHINGTON, D.C.", x, y + 56, { width: W, align: "center" });

  doc.rect(x + 16, y + 76, 64, 64).fillOpacity(0.15).fill("#ffffff").fillOpacity(1);
  doc.fillColor("#fff").fontSize(11).font("Helvetica-Bold").text(name, x + 92, y + 78, { width: W - 110 });
  doc.fontSize(9).fillColor(BRASS_LIGHT).font("Helvetica").text(idNumber, x + 92, y + 96);

  let ly = y + 118;
  doc.fontSize(8.5).fillColor("#C7CEDB").font("Helvetica");
  for (const line of lines) {
    doc.text(line, x + 92, ly, { width: W - 110 });
    ly += 13;
  }

  doc.fontSize(7).fillColor("#9aa4b8").text("SIGNATURE: ______________", x + 16, y + H - 40);
  doc.text("VALID UNTIL: 2026-2027", x + 16, y + H - 28);

  let bx = x + 16;
  for (let i = 0; i < 26; i++) {
    const w = i % 3 === 0 ? 1.4 : 0.8;
    doc.rect(bx, y + H - 16, w, 10).fill("#fff");
    bx += 3.5;
  }

  doc.save();
  doc.rotate(-90, { origin: [x + W - 10, y + H - 60] });
  doc.fontSize(10).font("Helvetica-Bold").fillColor("#fff").text(roleLabel, x + W - 10 - 90, y + H - 65, { width: 180, align: "center" });
  doc.restore();

  doc.restore();
}

// GET /api/documents/id-card — real PDF, generated from the logged-in user's actual data.
router.get("/id-card", requireAuth, async (req, res) => {
  const { role, full_name, id } = req.user;
  let idNumber = `NBU-${String(id).padStart(4, "0")}`;
  let lines = [];
  let roleLabel = ROLE_LABELS[role] || role.toUpperCase();

  if (role === "student") {
    const { rows } = await pool.query("SELECT * FROM students WHERE user_id = $1", [req.user.id]);
    const s = rows[0];
    if (s) {
      idNumber = s.student_number;
      lines = [s.program, `${s.level} · ${s.term}`];
      if (s.level && s.level.toLowerCase().includes("certificate")) roleLabel = "CERTIFICATION STUDENT";
    } else {
      lines = ["No academic record on file"];
    }
  } else if (role === "faculty" || role === "staff" || role === "mentor") {
    lines = [role === "staff" ? "Registrar Office" : role === "mentor" ? "Academic Mentor" : "Faculty Member", "Nation Builders University"];
  } else if (role === "boardDirector" || role === "boardAdvisor") {
    lines = ["Governing Board", "Nation Builders University"];
  }

  const doc = new PDFDocument({ size: "A4", margin: 0 });
  res.setHeader("Content-Type", "application/pdf");
  res.setHeader("Content-Disposition", `attachment; filename="NBU_ID_${idNumber}.pdf"`);
  doc.pipe(res);
  drawCard(doc, { roleLabel, name: full_name, idNumber, lines });
  doc.end();
});

// GET /api/documents/admission-form — public, blank template (no personal data).
router.get("/admission-form", async (req, res) => {
  const doc = new PDFDocument({ size: "A4", margin: 40 });
  res.setHeader("Content-Type", "application/pdf");
  res.setHeader("Content-Disposition", `attachment; filename="NBU_Admission_Form_2026-2027.pdf"`);
  doc.pipe(res);

  doc.image(LOGO_BUFFER, 40, 30, { width: 60, height: 60 });
  doc.fontSize(18).font("Helvetica-Bold").fillColor(INK).text("Nation Builders University", 110, 35);
  doc.fontSize(9).font("Helvetica").fillColor(SLATE)
    .text("1500 K Street NW, Washington, DC, USA", 110, 58)
    .text("Email: info@nationbuilderuniversity.com  ·  Phone: (771) 241-9259", 110, 70);

  doc.moveDown(3);
  let y = 110;
  doc.rect(40, y, 515, 20).fill(BRASS);
  doc.fillColor("#fff").fontSize(12).font("Helvetica-Bold").text("ADMISSION FORM — 2026-2027", 40, y + 4, { width: 515, align: "center" });
  y += 34;

  function section(title) {
    doc.rect(40, y, 515, 16).fill("#EFEAE0");
    doc.fillColor(INK).fontSize(10).font("Helvetica-Bold").text(title, 46, y + 3);
    y += 24;
  }
  function field(label, xOff = 40, width = 240) {
    doc.fontSize(8.5).font("Helvetica-Bold").fillColor(INK).text(label, xOff, y, { width });
    doc.moveTo(xOff, y + 13).lineTo(xOff + width - 10, y + 13).strokeColor("#ccc").stroke();
  }
  function row(labelA, labelB) {
    field(labelA, 40, 245);
    field(labelB, 300, 255);
    y += 22;
  }

  section("ADMISSION DETAILS");
  row("Admission No.", "Admission Date");
  row("Registration No.", "Enrollment No.");
  row("Program / Track", "Admission Type");
  row("Roll No.", "Medium");

  section("PERSONAL DETAILS");
  row("Student Name", "Gender");
  row("Date of Birth", "Nationality");
  row("Mobile No.", "Email");
  row("WhatsApp No.", "Alternate No.");
  row("Address", "Blood Group");

  section("FAMILY DETAILS");
  row("Father's Name", "Father's Occupation");
  row("Mother's Name", "Mother's Occupation");
  row("Guardian's Name (if applicable)", "Guardian's Contact");

  section("PREVIOUS ACADEMIC DETAILS");
  row("Attended Institution", "Last Program/Class");
  row("Enrolled Session", "Enrolled Year");

  if (y > 650) { doc.addPage(); y = 40; }
  section("DECLARATION & SIGNATURE");
  doc.fontSize(8.5).font("Helvetica").fillColor(SLATE)
    .text("I hereby certify that the above information is true and correct to the best of my knowledge.", 40, y, { width: 515 });
  y += 40;
  doc.moveTo(40, y).lineTo(220, y).strokeColor("#ccc").stroke();
  doc.moveTo(320, y).lineTo(500, y).strokeColor("#ccc").stroke();
  doc.fontSize(8).text("Applicant Signature", 40, y + 4);
  doc.fontSize(8).text("Date", 320, y + 4);

  doc.fontSize(7.5).fillColor(SLATE).text(
    "For inquiries: admissions@nationbuilderuniversity.com · This is an application form only — submission does not guarantee admission.",
    40, 780, { width: 515, align: "center" }
  );

  doc.end();
});

module.exports = router;
